// Format tanggal dan data untuk tiap task yang mendekati deadline
const items = $input.all();

if (items.length === 0 || !items[0].json.id) {
  return [];
}

return items.map(item => {
  const task = item.json;
  const d = new Date(task.deadline);

  return {
    json: {
      ...task,
      priority_label: (task.priority || 'Medium').charAt(0).toUpperCase() + (task.priority || 'Medium').slice(1),
      formatted_deadline: d.toLocaleString('id-ID', {
        day: 'numeric',
        month: 'long',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      })
    }
  };
});

